{
  "items": [
    {
      "name": "mul_le_of_forall_lt_of_nonneg",
      "module_name": "Mathlib.Algebra.Order.Field.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} [inst : Field α] [inst_1 : LinearOrder α] [IsStrictOrderedRing α] {a b c : α},\n  0 ≤ a → 0 ≤ c → (∀ a' ≥ 0, a' < a → ∀ b' ≥ 0, b' < b → a' * b' ≤ c) → a * b ≤ c"
    },
    {
      "name": "Order.le_of_lt_add_one",
      "module_name": "Mathlib.Algebra.Order.SuccPred",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {x y : α} [inst : LinearOrder α] [inst_1 : Add α] [inst_2 : One α] [SuccAddOrder α], x < y + 1 → x ≤ y"
    },
    {
      "name": "sq_lt_sq'",
      "module_name": "Mathlib.Algebra.Order.Ring.Abs",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : Ring α] [inst_1 : LinearOrder α] [IsStrictOrderedRing α] {a b : α},\n  -b < a → a < b → a ^ 2 < b ^ 2"
    },
    {
      "name": "LinearOrderedSemiField.toDenselyOrdered",
      "module_name": "Mathlib.Algebra.Order.Field.Basic",
      "kind": "instance",
      "type": "∀ {α : Type u_2} [inst : Semifield α] [inst_1 : PartialOrder α] [PosMulReflectLT α] [IsStrictOrderedRing α],\n  DenselyOrdered α"
    },
    {
      "name": "mul_self_le_mul_self_of_le_of_neg_le",
      "module_name": "Mathlib.Algebra.Order.Ring.Unbundled.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Ring R] [inst_1 : LinearOrder R] {a b : R} [MulPosMono R] [PosMulMono R] [AddLeftMono R],\n  a ≤ b → -a ≤ b → a * a ≤ b * b"
    }
  ]
}
